with parsed as (select id, level, latency_ms, status_code, context, coalesce(context['trace'], 'direct') as trace_or_default, cast((status_code & 2) != 0 as int) as is_flagged, get_json_object(payload_json, '$.user.id') as user_id from app_logs) select level, case when status_code >= 439 then 'LARGE' else 'SMALL' end as status_code_tier, round(avg(latency_ms), 2) as avg_latency_ms, approx_percentile(latency_ms, 0.5) as latency_ms_p50, avg(is_flagged) as avg_is_flagged from parsed group by level, case when status_code >= 439 then 'LARGE' else 'SMALL' end having avg_is_flagged >= 0 order by status_code_tier asc
